using System;
using UnityEngine;

namespace WanjieScroll.UI.Views
{
    /// <summary>
    /// Immutable brush silhouette samples, derived from ComboNumbers/0–9.png,
    /// except 7: its source asset incorrectly depicts 1, so author its strokes here.
    /// 64x96 source grid retains the original 2:3 canvas and transparent margins.
    /// Each base64 record is x, y, alpha, luminance; no image is loaded at runtime.
    /// This module owns decoding/cache only; animation belongs to ComboInkGraphic.
    /// </summary>
    internal static class ComboBrushPointCloud
    {
        internal struct Point
        {
            internal Vector2 Position;
            internal float Alpha;
            internal float Luminance;
            internal float Stretch;
            internal Vector2 Direction;
        }

        private static readonly Point[][] Cache = new Point[10][];
        private static readonly string[] Encoded =
        {
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
        };

        internal static Point[] Get(char digit)
        {
            int index = digit - '0';
            if (index < 0 || index > 9) return Array.Empty<Point>();
            if (Cache[index] != null) return Cache[index];
            byte[] bytes = index == 7 ? BuildSevenSamples() : Convert.FromBase64String(Encoded[index]);
            var points = new Point[bytes.Length / 4];
            var coverage = new float[64 * 96];
            for (int i = 0; i < bytes.Length; i += 4)
                coverage[bytes[i] + bytes[i + 1] * 64] = bytes[i + 2] / 255f;
            for (int i = 0; i < points.Length; i++)
            {
                int offset = i * 4;
                points[i] = new Point
                {
                    Position = new Vector2(((bytes[offset] + 0.5f) / 64f - 0.5f) * (2f / 3f),
                        0.5f - (bytes[offset + 1] + 0.5f) / 96f),
                    Alpha = bytes[offset + 2] / 255f,
                    Luminance = bytes[offset + 3] / 255f,
                    Direction = EstimateDirection(coverage, bytes[offset], bytes[offset + 1])
                };
            }
            Cache[index] = points;
            return points;
        }

        // Same 64x96 coordinate space as the other glyphs. A long top bar and
        // descending diagonal are deliberately distinct from 1's upright stem
        // and bottom foot. Pressure tapers at the entry and the lower-left tip.
        private static byte[] BuildSevenSamples()
        {
            const int steps = 80;
            var centers = new Vector2[steps * 2];
            var radii = new float[centers.Length];
            for (int i = 0; i < steps; i++)
            {
                float t = i / (steps - 1f);
                centers[i] = new Vector2(Mathf.Lerp(12f, 49f, t),
                    Mathf.Lerp(25f, 21f, t) - Mathf.Sin(t * Mathf.PI) * 0.7f);
                radii[i] = Mathf.Lerp(0.5f, 3.8f, Mathf.Clamp01(t * 5f));
                float u = 1f - t;
                centers[steps + i] = u * u * u * new Vector2(49f, 21f) +
                    3f * u * u * t * new Vector2(46f, 36f) +
                    3f * u * t * t * new Vector2(31f, 64f) +
                    t * t * t * new Vector2(22f, 79f);
                radii[steps + i] = Mathf.Lerp(4.1f, 0.25f, t * t) *
                    (1f + 0.08f * Mathf.Sin(t * Mathf.PI));
            }
            var bytes = new System.Collections.Generic.List<byte>();
            for (int y = 0; y < 96; y++)
            for (int x = 0; x < 64; x++)
            {
                var sample = new Vector2(x + 0.5f, y + 0.5f);
                float edge = float.NegativeInfinity;
                for (int i = 0; i < centers.Length; i++)
                    edge = Mathf.Max(edge, radii[i] - Vector2.Distance(sample, centers[i]));
                float alpha = Mathf.Clamp01(edge + 0.5f);
                if (alpha < 32f / 255f) continue;
                bytes.Add((byte)x);
                bytes.Add((byte)y);
                bytes.Add((byte)Mathf.RoundToInt(alpha * 255f));
                // Restrained stable bristle grain; never animated noise.
                bytes.Add((byte)(205 + (x * 17 + y * 11) % 50));
            }
            return bytes.ToArray();
        }

        // Local coverage covariance follows the long axis of a brush stroke.
        // Computed once per cached glyph, never during mesh rebuilds.
        private static Vector2 EstimateDirection(float[] coverage, int x, int y)
        {
            float weight = 0f, sx = 0f, sy = 0f, xx = 0f, xy = 0f, yy = 0f;
            for (int dy = -3; dy <= 3; dy++)
            for (int dx = -3; dx <= 3; dx++)
            {
                int px = x + dx, py = y + dy;
                if (px < 0 || px >= 64 || py < 0 || py >= 96) continue;
                float w = coverage[px + py * 64];
                weight += w;
                sx += dx * w;
                sy -= dy * w;
                xx += dx * dx * w;
                xy -= dx * dy * w;
                yy += dy * dy * w;
            }
            if (weight < 0.01f) return Vector2.up;
            xx -= sx * sx / weight;
            xy -= sx * sy / weight;
            yy -= sy * sy / weight;
            if (Mathf.Abs(xx - yy) + Mathf.Abs(xy) < 0.01f) return Vector2.up;
            float angle = 0.5f * Mathf.Atan2(2f * xy, xx - yy);
            return new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
        }
    }
}
